  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਮੁੱਖ ਪਾਤਰਾਂ (ਕਰਤਾਰਾ ਅਤੇ ਸਰਦਾਰਾ) ਦਾ ਚਰਿੱਤਰ ਚਿਤਰਣ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੜ੍ਹ ਵਰਗੀਆਂ ਕੁਦਰਤੀ ਆਫ਼ਤਾਂ ਸਮੇਂ ਮਨੁੱਖੀ ਸਬੰਧਾਂ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪੈਂਦਾ ਹੈ? ਪਾਠ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਅੰਤ ਵਿੱਚ ਸਰਦਾਰੇ ਦੇ ਆਪਣੇ ਪੁੱਤਰ ਨਾਲ ਕੀਤੇ ਸੰਵਾਦ ਦਾ ਕੀ ਮਹੱਤਵ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚੋਂ ਹੜ੍ਹ ਦੇ ਪਾਣੀ ਦੀ ਗਤੀ ਅਤੇ ਆਵਾਜ਼ ਦਾ ਵਰਣਨ ਕਿਵੇਂ ਕੀਤਾ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
