  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਹਾਣੀ ਵਿੱਚ 'ਵਾਹਿਗੁਰੂ' ਦੇ ਜ਼ਿਕਰ ਦਾ ਕੀ ਮਹੱਤਵ ਹੈ? ਇਹ ਕਿਹੜੇ ਵਿਸ਼ਵਾਸ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਵਿੱਚ ਪਾਤਰਾਂ ਦੇ ਮਨੋਵਿਗਿਆਨਕ ਪਹਿਲੂਆਂ ਨੂੰ ਕਿਵੇਂ ਦਰਸਾਇਆ ਗਿਆ ਹੈ? ਉਨ੍ਹਾਂ ਦੇ ਡਰ, ਚਿੰਤਾ ਅਤੇ ਰਾਹਤ ਦੀਆਂ ਭਾਵਨਾਵਾਂ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਹਾਣੀ ਦੇ ਅੰਤ ਵਿੱਚ ਦੋਵਾਂ ਪਰਿਵਾਰਾਂ ਦੇ ਰਿਸ਼ਤਿਆਂ ਵਿੱਚ ਆਈ ਨਵੀਂ ਸ਼ੁਰੂਆਤ ਬਾਰੇ ਵਿਸਥਾਰ ਵਿੱਚ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਤੋਂ ਪ੍ਰੇਰਣਾ ਲੈ ਕੇ ਤੁਸੀਂ ਆਪਣੇ ਜੀਵਨ ਵਿੱਚ ਆਪਸੀ ਸਹਾਇਤਾ ਅਤੇ ਭਾਈਚਾਰੇ ਨੂੰ ਕਿਵੇਂ ਅਪਣਾ ਸਕਦੇ ਹੋ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੜ੍ਹਾਂ ਨੇ ਲੋਕਾਂ ਦੇ ਘਰ-ਬਾਰ ਤਬਾਹ ਕਰ ਦਿੱਤੇ ਸਨ, ਪਰ ਇਸ ਦੇ ਬਾਵਜੂਦ ਰਿਸ਼ਤੇ ਕਿਵੇਂ ਮਜ਼ਬੂਤ ਹੋ ਗਏ? ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਅਨੁਸਾਰ, ਹੜ੍ਹਾਂ ਨੇ ਕਿਹੜੀਆਂ ਨਕਾਰਾਤਮਕ ਭਾਵਨਾਵਾਂ ਨੂੰ ਖਤਮ ਕਰਕੇ ਸਕਾਰਾਤਮਕ ਭਾਵਨਾਵਾਂ ਨੂੰ ਉਜਾਗਰ ਕੀਤਾ? ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਰਿਸ਼ਤਿਆਂ ਦੇ ਰੇਸ਼ਮੀ ਧਾਗੇ' ਤੋਂ ਲੇਖਕ ਦਾ ਕੀ ਭਾਵ ਹੈ? ਇਸ ਤੁਲਨਾ ਦੀ ਮਹੱਤਤਾ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜਿਆਂ ਵਿੱਚ ਦੱਸੇ ਗਏ 'ਰਿਸ਼ਤਿਆਂ ਦੇ ਮਹੱਤਵ' ਅਤੇ 'ਮੁਸੀਬਤ ਵਿੱਚ ਮਦਦ' ਦੀ ਭਾਵਨਾ ਨੂੰ ਪਾਠ ਦੇ ਪ੍ਰਸੰਗ ਵਿੱਚ ਸਮਝਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸੇ ਕੁਦਰਤੀ ਆਫ਼ਤ ਦੇ ਸਮੇਂ ਮਨੁੱਖੀ ਰਿਸ਼ਤਿਆਂ ਵਿੱਚ ਕੀ ਬਦਲਾਅ ਆਉਂਦੇ ਹਨ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
