  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਰਸਾਏ ਗਏ ਦੋ ਪਰਿਵਾਰਾਂ ਦੇ ਆਪਸੀ ਰਿਸ਼ਤਿਆਂ ਦੀ ਡੂੰਘਾਈ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਸਮਝ ਦੀ ਪਰਖ' ਵਾਲੇ ਭਾਗ ਵਿੱਚ ਪੁੱਛੇ ਗਏ ਪ੍ਰਸ਼ਨਾਂ ਦਾ ਉਦੇਸ਼ ਕੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ 'ਕੁਦਰਤੀ ਆਫ਼ਤ' ਦੇ ਪ੍ਰਭਾਵਾਂ ਨੂੰ ਕਿਵੇਂ ਦਰਸਾਇਆ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਰਿਸ਼ਤੇ ਬਚਾਉਣ ਲਈ ਸਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?' ਇਸ ਪ੍ਰਸ਼ਨ ਦਾ ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਵਿਸਥਾਰਪੂਰਵਕ ਉੱਤਰ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦੱਸੀਆਂ ਗਈਆਂ ਸਕਾਰਾਤਮਕ ਭਾਵਨਾਵਾਂ (ਮੋਹ-ਮੁਹੱਬਤ, ਭਾਈਚਾਰਾ) ਨੂੰ ਆਪਣੇ ਜੀਵਨ ਵਿੱਚ ਕਿਵੇਂ ਅਪਣਾਇਆ ਜਾ ਸਕਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੜ੍ਹਾਂ ਵਰਗੀਆਂ ਬਿਪਤਾਵਾਂ ਮਨੁੱਖੀ ਸਬੰਧਾਂ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀਆਂ ਹਨ, ਇਸ ਬਾਰੇ ਪਾਠ ਕੀ ਸੰਦੇਸ਼ ਦਿੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਸ਼ੁਰੂਆਤੀ ਵਾਕ "ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਬੀਬੀਆਂ ਵੀ ਸਿੱਲ੍ਹੀਆਂ ਅੱਖਾਂ ਨਾਲ ਇੱਕ-ਦੂਜੀ ਨੂੰ ਗਲ ਲਾ ਰਹੀਆਂ ਸਨ" ਦਾ ਭਾਵ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦੱਸੇ ਗਏ 'ਸਿੱਖਣ ਨਤੀਜਿਆਂ' ਦੀ ਮਹੱਤਤਾ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਅੰਤ ਵਿੱਚ ਦਿੱਤੀ ਗਈ 'ਭਾਈਚਾਰਾ' ਸ਼ਬਦ ਦੀ ਪਰਿਭਾਸ਼ਾ ਨੂੰ ਪਾਠ ਦੇ ਮੁੱਖ ਭਾਵ ਨਾਲ ਜੋੜ ਕੇ ਸਮਝਾਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੀ ਤੁਹਾਨੂੰ ਲੱਗਦਾ ਹੈ ਕਿ ਅਜਿਹੀਆਂ ਘਟਨਾਵਾਂ ਅਸਲ ਜੀਵਨ ਵਿੱਚ ਵੀ ਵਾਪਰਦੀਆਂ ਹਨ, ਜਿੱਥੇ ਮੁਸੀਬਤ ਰਿਸ਼ਤਿਆਂ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰਦੀ ਹੈ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਆਪਣੇ ਵਿਚਾਰ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦਾ ਸਿਰਲੇਖ "ਪੰਜਾਬੀ ਪਾਠ-ਮਾਲਾ" ਹੈ, ਇਸ ਪਾਠ ਨੂੰ ਇਸ ਮਾਲਾ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰਨ ਦਾ ਕੀ ਉਦੇਸ਼ ਹੋ ਸਕਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਰਸਾਏ ਗਏ ਮਨੁੱਖੀ ਜਜ਼ਬਾਤਾਂ (ਪਿਆਰ, ਦੁੱਖ, ਹਮਦਰਦੀ) ਬਾਰੇ ਵਿਸਥਾਰ ਨਾਲ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('95067fb9-e726-41f6-8630-b185347289bb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ਾਮ ਦਾ ਵੇਲਾ ਸੀ। ਅਸਮਾਨ ਕਾਲੇ ਬੱਦਲਾਂ ਨਾਲ ਕੱਜਿਆ ਹੋਇਆ ਸੀ। ਗੁਰੂ ਘਰੋਂ ਸਪੀਕਰ ਉੱਤੇ ਆਈ ਅਵਾਜ਼ ਨੇ ਸਾਰੇ ਪਿੰਡ ਵਾਸੀਆਂ ਨੂੰ ਫਿਕਰਾਂ ਵਿੱਚ ਪਾ ਦਿੱਤਾ। ਪਾਠੀ ਸਿੰਘ ਨੇ ਪਿੰਡ ਵਾਸੀਆਂ ਨੂੰ ਹੜ੍ਹਾਂ ਬਾਰੇ ਸੁਚੇਤ ਕਰਦਿਆਂ ਕਿਹਾ, ÒÒਪ੍ਰਸ਼ਾਸਨ ਦਾ ਸੁਨੇਹਾ ਆਇਆ ਹੈ ਕਿ ਤੁਰੰਤ ਪਿੰਡ ਛੱਡ ਕੇ ਸੁਰੱਖਿਅਤ ਥਾਵਾਂ ਉੱਤੇ ਚਲੇ ਜਾਓ। ਦਰਿਆ ਵਿੱਚ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਹੈ, ਸਾਵਧਾਨ ਰਹੋ।ÓÓ$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f1063dcf-c6ab-461a-8717-db44dcac0eaa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਸੁਣ ਕੇ ਲੋਕਾਂ ਵਿੱਚ ਘੁਸਰ-ਮੁਸਰ ਹੋਣ ਲੱਗੀ। ਵੈਸੇ ਤਾਂ ਪਿਛਲੇ ਕਈ ਦਿਨਾਂ ਤੋਂ ਬੇਮੌਸਮੇ ਮੀਂਹ ਨੇ ਲੋਕਾਂ ਦੇ ਸਾਹ ਸੂਤੇ ਹੋਏ ਸਨ ਪਰ ਹੜ੍ਹਾਂ ਬਾਰੇ ਕਿਸੇ ਨੇ ਬਹੁਤੀ ਚਿੰਤਾ ਨਹੀਂ ਕੀਤੀ ਸੀ। ਇਹ ਪਿੰਡ ਸਤਲੁਜ ਦਰਿਆ ਦੇ ਬਿਲਕੁਲ ਨੇੜੇ ਸੀ। ਪਹਾੜੀ ਖੇਤਰਾਂ ਵਿੱਚ ਵੀ ਹਾਲਾਤ ਸੁਖਾਵੇਂ ਨਹੀਂ ਸਨ। ਡੈਮਾਂ ਵਿੱਚ ਪਾਣੀ ਦਾ ਪੱਧਰ ਵੱਧ ਰਿਹਾ ਸੀ। ਹੁਣ ਜਦੋਂ ਡੈਮ ਵਿੱਚੋਂ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਤਾਂ ਹੜ੍ਹਾਂ ਦਾ ਖ਼ਤਰਾ ਹਕੀਕਤ ਬਣ ਗਿਆ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('879c7ae0-1054-457c-ab0f-2619de6b0962', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਪਿੰਡ ਬਸੰਤਪੁਰ ਸੀ - ਨਾਂ ਵਾਂਗ ਹੀ ਸੋਹਣਾ। ਹਰਿਆਲੀ, ਖੇਤਾਂ ਵਿੱਚ ਲਹਿਲਹਾਉਂਦੀਆਂ ਫਸਲਾਂ, ਖੁੱਲ੍ਹੇ ਵਿਹੜਿਆਂ ਵਾਲੇ ਘਰ, ਗਲੀਆਂ ਵਿੱਚ ਕਿਲਕਾੜੀਆਂ ਮਾਰਦੇ ਬੱਚੇ ਤੇ ਸੱਥ ਵਿੱਚ ਬਾਬਿਆਂ ਦੀਆਂ ਗੱਲਾਂ - ਇਹ ਸਭ ਬਸੰਤਪੁਰ ਨੂੰ ਨਿਆਰੀ ਦਿੱਖ ਬਖਸ਼ਦਾ ਸੀ ਪਰ ਅੱਜ ਇਹ ਪਿੰਡ ਗੰਭੀਰ ਬਿਪਤਾ ਨਾਲ ਦੋ-ਚਾਰ ਹੋਣ ਜਾ ਰਿਹਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ea12a8bb-57bf-4eb7-bbe9-856577929d52', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਨਾਊਂਸਮੈਂਟ ਸੁਣਦਿਆਂ ਹੀ ਲੋਕਾਂ ਨੇ ਹੱਥਲੇ ਕੰਮ ਰੋਕ ਦਿੱਤੇ। ਉਹਨਾਂ ਨੇ ਆਪਣੀਆਂ ਕੀਮਤੀ ਵਸਤਾਂ ਇਕੱਠੀਆਂ ਕਰਨੀਆਂ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੀਆਂ-ਜ਼ਰੂਰੀ ਕਾਗਜ਼-ਪੱਤਰ, ਨਕਦੀ, ਮੋਬਾਈਲ ਤੇ ਕੁਝ ਸੁੱਕਾ ਰਾਸ਼ਨ। ਸਭ ਤੋਂ ਵੱਡੀ ਅੌਖੀ ਘੜੀ ਕਿਸਾਨਾਂ ਲਈ ਡੰਗਰਾਂ ਦੀ ਸੀ। ਇਹਨਾਂ ਨੂੰ ਛੱਡਣਾ ਵੀ ਸੰਭਵ ਨਹੀਂ ਸੀ ਤੇ ਨਾਲ ਲਿਜਾਣਾ ਵੀ ਮੁਸ਼ਕਲ ਸੀ। ਕਈਆਂ ਨੇ ਰੱਸੇ ਖੋਲ੍ਹ ਦਿੱਤੇ ਕਿ ਜਾਨਵਰ ਆਪਣੇ-ਆਪ ਬਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰ ਲੈਣ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b64add91-2f5c-4099-80d8-eee355b7ea4f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਪਿੰਡ ਸਤਲੁਜ ਦਰਿਆ ਦੇ ਬਿਲਕੁਲ ਨੇੜੇ ਸੀ। ਪਹਾੜੀ ਖੇਤਰਾਂ ਵਿੱਚ ਵੀ ਹਾਲਾਤ ਸੁਖਾਵੇਂ ਨਹੀਂ ਸਨ। ਡੈਮਾਂ ਵਿੱਚ ਪਾਣੀ ਦਾ ਪੱਧਰ ਵੱਧ ਰਿਹਾ ਸੀ। ਹੁਣ ਜਦੋਂ ਡੈਮ ਵਿੱਚੋਂ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਤਾਂ ਹੜ੍ਹਾਂ ਦਾ ਖ਼ਤਰਾ ਹਕੀਕਤ ਬਣ ਗਿਆ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c2787713-acd8-4d45-bd06-03fbf7e801d0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਘਰਾਂ ਨੇ ਬੱਕਰਿਆਂ, ਗਾਵਾਂ ਅਤੇ ਮੱਝਾਂ ਨੂੰ ਉੱਚੀਆਂ ਥਾਵਾਂ ਵੱਲ ਛੱਡ ਦਿੱਤਾ। ਕਈ ਪਰਿਵਾਰ ਔਰਤਾਂ ਤੇ ਬੱਚਿਆਂ ਨੂੰ ਲੈ ਕੇ ਪਿੰਡ ਤੋਂ ਬਾਹਰ ਜਾਣ ਲੱਗੇ ਪਰ ਅਜੇ ਵੀ ਕਈਆਂ ਨੂੰ ਯਕੀਨ ਨਹੀਂ ਸੀ ਕਿ ਪਾਣੀ ਇੱਥੇ ਤੱਕ ਪਹੁੰਚ ਸਕਦਾ ਹੈ। ਸਵੇਰ ਹੁੰਦਿਆਂ ਹੀ ਪਿੰਡ ਦਾ ਦ੍ਰਿਸ਼ ਪੂਰੀ ਤਰ੍ਹਾਂ ਬਦਲ ਗਿਆ। ਜਿਸ ਥਾਂ ਕਦੇ ਸੁਨਹਿਰੀ ਝੋਨੇ ਦੀ ਫਸਲ ਖੜ੍ਹੀ ਸੀ, ਉੱਥੇ ਹੁਣ ਸਿਰਫ਼ ਪਾਣੀ ਹੀ ਪਾਣੀ ਸੀ। ਲੱਗਦਾ ਸੀ ਜਿਵੇਂ ਪਿੰਡ ਸਮੁੰਦਰ ਵਿੱਚ ਬਦਲ ਗਿਆ ਹੋਵੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('053396aa-8cf6-4b70-830d-b56862d6e2f9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰਾਂ ਦੇ ਆਹਮਣੇ-ਦੁਆਲ੍ਹੇ ਪਾਣੀ ਵਗ ਰਿਹਾ ਸੀ, ਨੀਵੇਂ ਘਰਾਂ ਦੀਆਂ ਤਾਂ ਬੱਸ ਛੱਤਾਂ ਹੀ ਨਜ਼ਰ ਆਉਂਦੀਆਂ ਸਨ। ਕਈ ਲੋਕਾਂ ਨੇ ਆਪਣੇ ਘਰਾਂ ਦੀਆਂ ਛੱਤਾਂ ਉੱਤੇ ਝੁੱਗੀਆਂ ਬਣਾ ਲਈਆਂ। ਹੁਣ ਇਹ ਝੁੱਗੀਆਂ ਹੀ ਆਰਜ਼ੀ ਆਸਰਾ ਸਨ। ਇਹਨਾਂ ਵਿੱਚ ਹੀ ਚੁੱਲ੍ਹਾ-ਚੌਂਕਾ ਤੇ ਇਹਨਾਂ ਵਿੱਚ ਹੀ ਬਹਿਣ-ਪੈਣ ਦਾ ਇੰਤਜ਼ਾਮ ਹੋ ਰਿਹਾ ਸੀ। ਉੱਧਰੋਂ ਇੰਦਰ ਦੇਵਤਾ ਵੀ ਲਗਾਤਾਰ ਲੋਕਾਂ ਦੇ ਸਬਰ ਦਾ ਇਮਤਿਹਾਨ ਲੈ ਰਿਹਾ ਸੀ। ਲੋਕ ਇੱਕ-ਦੂਜੇ ਨੂੰ ਦਿਲਾਸਾ ਦਿੰਦੇ ਮਦਦ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a84b7766-e794-4495-97e2-c110ad976f88', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਿੰਡ ਵਿੱਚ ਕਰਤਾਰਾ ਤੇ ਸਰਦਾਰਾ ਦੋਵੇਂ ਮੰਨੇ-ਪ੍ਰਮੰਨੇ ਕਿਸਾਨ ਸਨ। ਦੋਵਾਂ ਨੇ ਥੋੜ੍ਹੀ-ਜਿਹੀ ਜ਼ਮੀਨ ਵਿੱਚੋਂ ਵੀ ਭਰਵੀਆਂ ਫਸਲਾਂ ਲੈ ਕੇ ਆਪਣੇ ਘਰਾਂ ਨੂੰ ਪੈਰਾਂ-ਸਿਰ ਕੀਤਾ ਹੋਇਆ ਸੀ। ਭਾਵੇਂ ਦੋਵੇਂ ਚਾਚੇ-ਤਾਏ ਦੇ ਪੁੱਤਰ ਸਨ ਪਰ ਆਪਸੀ ਬੋਲ-ਬਾਣੀ ਬੰਦ ਸੀ। ਪਿਛਲੇ ਸਾਲ ਇੱਕ ਵੱਟ ਦੇ ਰੌਲੇ ਤੋਂ ਸ਼ੁਰੂ ਹੋਈ ਗੱਲ ਕੋਰਟ-ਕਚਹਿਰੀ ਤੱਕ ਪਹੁੰਚ ਗਈ ਸੀ। ਉਸ ਦਿਨ ਤੋਂ ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਨੇ ਇੱਕ-ਦੂਜੇ ਨੂੰ ਬੁਲਾਉਣਾ ਛੱਡ ਦਿੱਤਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4800c9d2-ec6a-4787-aec4-291d73a1f3bf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵਾਂ ਦੇ ਸਾਂਝੇ ਰਿਸ਼ਤੇਦਾਰਾਂ ਨੇ ਸਮਝਾਉਣ ਦੀ ਬੜੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ ਪਰ ਦੋਵੇਂ ਧੀਰਾਂ ਟੱਸ ਤੋਂ ਮੱਸ ਨਹੀਂ ਹੋ ਰਹੀਆਂ ਸਨ। ਕੋਈ ਸਮਾਂ ਸੀ, ਜਦੋਂ ਦੋਵੇਂ ਪਰਿਵਾਰ ਰਲ-ਮਿਲ ਕੇ ਤਿਉਹਾਰ ਮਨਾਉਂਦੇ ਸਨ ਪਰ ਹੁਣ ਰੰਜਸ਼ਾਂ ਦੀਆਂ ਕੰਧਾਂ ਨੇ ਇਹ ਸਾਰਾ ਕੁਝ ਤੋੜ ਦਿੱਤਾ ਸੀ। ਹੁਣ ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੇ ਘਰ ਆਹਮੋ-ਸਾਹਮਣੇ ਸਨ ਤੇ ਹੜ੍ਹ ਦੇ ਪਾਣੀ ਵਿੱਚ ਘਿਰੇ ਹੋਏ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9d7d1ccb-6f12-4d82-b12d-b0420d398989', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵਾਂ ਨੇ ਆਪਣੇ ਕੋਠਿਆਂ ਉੱਤੇ ਪਲਾਸਟਿਕ ਦੀਆਂ ਤਰਪਾਲਾਂ ਤਾਣ ਕੇ ਝੁੱਗੀਆਂ ਬਣਾ ਲਈਆਂ। ਰਾਤੀਂ ਪਾਣੀ ਦੀ ਗੜਗੜਾਹਟ ਅਤੇ ਮੀਂਹ ਦੀਆਂ ਬੂੰਦਾਂ ਲੋਕਾਂ ਦੇ ਦਿਲਾਂ ਵਿੱਚ ਹੋਰ ਵੀ ਡਰ ਪੈਦਾ ਕਰ ਰਹੀਆਂ ਸਨ। ਕਰਤਾਰੇ ਦਾ ਘਰ ਪੁਰਾਣਾ ਸੀ। ਪਾਣੀ ਦੇ ਕਾਰਨ ਕੰਧਾਂ ਕਮਜ਼ੋਰ ਹੋ ਰਹੀਆਂ ਸਨ। ਸਰਦਾਰੇ ਦਾ ਘਰ ਨਵਾਂ ਸੀ ਤੇ ਕੁਝ ਮਜ਼ਬੂਤ ਲੱਗ ਰਿਹਾ ਸੀ। ਫਿਰ ਵੀ ਦੋਵੇਂ ਪਰਿਵਾਰ ਕੋਠਿਆਂ ਉੱਤੇ ਬੈਠੇ ਇੱਕ-ਦੂਜੇ ਵੱਲ ਚੋਰੀ-ਚੋਰੀ ਤੱਕ ਲੈਂਦੇ। ਭਾਵੇਂ ਸਰਦਾਰਾ ਕਰਤਾਰੇ ਨਾਲ ਬੋਲਦਾ ਨਹੀਂ ਸੀ ਪਰ ਉਸਦੇ ਘਰ ਦਾ ਫਿਕਰ ਉਸਨੂੰ ਵੀ ਬਹੁਤ ਸੀ। ਉਹ ਆਪਣੇ ਟੱਬਰ ਨੂੰ ਕਹਿੰਦਾ, 'ਕਰਤਾਰੇ ਦਾ ਘਰ ਡਿੱਗੂ-ਡਿੱਗੂ ਕਰਦੈ। ਇਹਨੂੰ ਛੱਡ ਕੇ ਚਲੇ ਜਾਣਾ ਚਾਹੀਦੈ, ਰੱਬ ਨਾ ਕਰੇ ਜੇ ਇਹ ਡਿੱਗ ਪਿਆ ਤਾਂ ਬੜਾ ਨੁਕਸਾਨ ਹੋ ਜਾਣਾ।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fd452af6-3c7f-4b1b-ab30-70962ac1366a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜੇ ਦਿਨ ਤੱਕ ਹਾਲਤ ਹੋਰ ਬਦਤਰ ਹੋ ਚੁੱਕੀ ਸੀ। ਅਚਾਨਕ ਕਰਤਾਰੇ ਦੇ ਘਰੋਂ ਜ਼ੋਰਦਾਰ ਖੜਾਕ ਹੋਇਆ। ਸਾਰਿਆਂ ਦਾ ਧਿਆਨ ਉਸ ਪਾਸੇ ਖਿੱਚਿਆ ਗਿਆ। ਇੱਕ ਕਮਰਾ ਬੁਰੀ ਤਰ੍ਹਾਂ ਢਹਿ ਪਿਆ ਸੀ ਤੇ ਦੂਜਾ ਵੀ ਡਿੱਗਣ ਵਾਲਾ ਸੀ। ਕਰਤਾਰੇ ਦੇ ਪਰਿਵਾਰ ਉੱਤੇ ਡਰ ਦਾ ਸਾਇਆ ਛਾ ਗਿਆ। ਸਭ ਤੋਂ ਵੱਡੀ ਸਮੱਸਿਆ ਇਹ ਸੀ ਕਿ ਜਿਸ ਕਮਰੇ ਤੋਂ ਕੋਠੇ ਉੱਤੇ ਜਾਣ ਵਾਲੀ ਪੌੜੀ ਸੀ, ਉਹ ਵੀ ਢਹਿ ਗਿਆ ਸੀ। ਹੁਣ ਹੇਠਾਂ ਉੱਤਰਨ ਦਾ ਰਸਤਾ ਨਹੀਂ ਬਚਿਆ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9b84b4b9-5bed-4ae3-8d6f-3bb099799e08', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਰਦਾਰੇ ਦੇ ਪਰਿਵਾਰ ਨੇ ਜਦੋਂ ਇਹ ਦ੍ਰਿਸ਼ ਦੇਖਿਆ ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਕੰਬ ਗਏ। ਸਾਰਾ ਟੱਬਬਰ ਵਾਹੋ-ਦਾਹੀ ਕਰਤਾਰੇ ਦੇ ਘਰ ਵੱਲ ਦੌੜਿਆ। ਸਰਦਾਰੇ ਦਾ ਮੁੰਡਾ ਤੁਰੰਤ ਘਰੋਂ ਇੱਕ ਵੱਡੀ ਪੌੜੀ ਲਿਆਇਆ। ਸਰਦਾਰੇ ਨੇ ਖੁਦ ਅੱਗੇ ਵਧ ਕੇ ਉਹ ਪੌੜੀ ਕਰਤਾਰੇ ਦੇ ਕੋਠੇ ਨਾਲ ਟਿਕਾਈ। ਕਰਤਾਰੇ ਦਾ ਪਰਿਵਾਰ ਹੜਬੜਾਹਟ ਵਿੱਚ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਪੌੜੀ ਰਾਹੀਂ ਹੇਠਾਂ ਉੱਤਰਿਆ। ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਬੱਚਿਆਂ ਨੂੰ ਉਤਾਰਿਆ ਗਿਆ, ਫਿਰ ਔਰਤਾਂ ਅਤੇ ਆਖਰ ਵਿੱਚ ਕਰਤਾਰਾ ਆਪ ਉੱਤਰਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5ef19122-1d1b-4f08-a297-7a86bf9bf9bb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਹੀ ਮਿੰਟਾਂ ਵਿੱਚ ਉਹ ਸਭ ਸਰਦਾਰੇ ਦੇ ਘਰ ਦੀ ਛੱਤ ਉੱਤੇ ਆ ਗਏ। ਅਜੇ ਉਹ ਸੰਭਲੇ ਵੀ ਨਹੀਂ ਸਨ ਕਿ ਦੂਜਾ ਕਮਰਾ ਵੀ ਧੜੰਮ ਕਰ ਕੇ ਡਿੱਗ ਗਿਆ। ਇਸੇ ਕਮਰੇ ਉੱਤੇ ਕੁਝ ਸਮਾਂ ਪਹਿਲਾਂ ਕਰਤਾਰੇ ਦਾ ਟੱਬਰ ਬੈਠਾ ਸੀ। ਜੇ ਉਹ ਉੱਪਰ ਹੀ ਰਹਿੰਦੇ ਤਾਂ ਜ਼ਰੂਰ ਕੋਈ ਭਾਣਾ ਵਾਪਰ ਜਾਣਾ ਸੀ। ਇਹ ਦੇਖ ਕੇ ਸਾਰਿਆਂ ਦੇ ਮੂੰਹੋਂ ਸ਼ੁਕਰਾਨੇ ਦੇ ਬੋਲ ਨਿਕਲਣ ਲੱਗੇ। ਬਾਹਰ ਮੀਂਹ ਹੋਰ ਤੇਜ਼ ਹੋ ਗਿਆ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a048d62d-c558-4201-acb1-7722c5f243ec', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵਾਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਵੀ ਹੰਝੂਆਂ ਦੀ ਝੜੀ ਲੱਗੀ ਹੋਈ ਸੀ ਪਰ ਇਹ ਹੰਝੂ ਦੁੱਖ ਦੇ ਨਹੀਂ ਸਨ। ਇਹ ਹੰਝੂ ਰਿਸ਼ਤਿਆਂ ਦੀ ਮੁਹੱਬਤ ਦੇ ਸਨ ਜਿਹੜੇ ਫੋਕੀਆਂ ਰੰਜਸ਼ਾਂ ਤੇ ਰੋਸਿਆਂ ਨੂੰ ਦਿਲਾਂ ਵਿੱਚੋਂ ਹੂੰਝ ਰਹੇ ਸਨ। ਕਰਤਾਰਾ ਭਿੱਜੀਆਂ ਅੱਖਾਂ ਨਾਲ ਸਰਦਾਰੇ ਦੇ ਗਲ ਲੱਗ ਕੇ ਕਹਿਣ ਲੱਗਾ, ''ਭਰਾ, ਮਾਫ਼ ਕਰ ਦੇ। ਅੱਜ ਜੇ ਤੂੰ ਨਾ ਹੁੰਦਾ ਤਾਂ ਸਾਡਾ ਕੀ ਬਣਦਾ!'' ਸਰਦਾਰਾ ਭਰੇ ਮਨ ਨਾਲ ਬੋਲਿਆ, ''ਬਚਾਉਣ ਵਾਲਾ ਤਾਂ ਵਾਹਿਗੁਰੂ ਹੈ ਵੀਰਿਆ। ਜੋ ਹੋਇਆ ਉਹ ਭੁੱਲ ਜਾ। ਅੱਜ ਤੋਂ ਆਪਣਾ ਕੋਈ ਰੋਸਾ ਨਹੀਂ, ਮੈਂ ਹੀ ਗਲਤ ਸਾਂ। ਆਪਣਾ ਸਾਰਾ ਝਗੜਾ ਇਸ ਕਮਰੇ ਦੇ ਨਾਲ ਹੀ ਮੁੱਕ ਗਿਆ ਸਮਝੀਂ।''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('02b41550-6821-420e-b60f-7c21ef7cd164', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜੇ ਦਿਨ ਤੱਕ ਹਾਲਤ ਹੋਰ ਬਦਤਰ ਹੋ ਚੁੱਕੀ ਸੀ। ਅਚਾਨਕ ਕਰਤਾਰੇ ਦੇ ਘਰੋਂ ਜ਼ੋਰਦਾਰ ਖੜਾਕ ਹੋਇਆ। ਸਾਰਿਆਂ ਦਾ ਧਿਆਨ ਉਸ ਪਾਸੇ ਖਿੱਚਿਆ ਗਿਆ। ਇੱਕ ਕਮਰਾ ਬੁਰੀ ਤਰ੍ਹਾਂ ਢਹਿ ਪਿਆ ਸੀ ਤੇ ਦੂਜਾ ਵੀ ਡਿੱਗਣ ਵਾਲਾ ਸੀ। ਕਰਤਾਰੇ ਦੇ ਪਰਿਵਾਰ ਉੱਤੇ ਡਰ ਦਾ ਸਾਇਆ ਛਾ ਗਿਆ। ਸਭ ਤੋਂ ਵੱਡੀ ਸਮੱਸਿਆ ਇਹ ਸੀ ਕਿ ਜਿਸ ਕਮਰੇ ਤੋਂ ਕੋਠੇ ਉੱਤੇ ਜਾਣ ਵਾਲੀ ਪੌੜੀ ਸੀ, ਉਹ ਵੀ ਢਹਿ ਗਿਆ ਸੀ। ਹੁਣ ਹੇਠਾਂ ਉੱਤਰਨ ਦਾ ਰਸਤਾ ਨਹੀਂ ਬਚਿਆ ਸੀ। ਸਰਦਾਰੇ ਦੇ ਪਰਿਵਾਰ ਨੇ ਜਦੋਂ ਇਹ ਦ੍ਰਿਸ਼ ਦੇਖਿਆ ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਕੰਬ ਗਏ। ਸਾਰਾ ਟੱਬਰ ਵਾਹੋ-ਦਾਹੀ ਕਰਤਾਰੇ ਦੇ ਘਰ ਵੱਲ ਦੌੜਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6b350c7c-462d-4407-8f7c-4a3d221afa4c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਰਦਾਰੇ ਦਾ ਮੁੰਡਾ ਤੁਰੰਤ ਘਰੋਂ ਇੱਕ ਵੱਡੀ ਪੌੜੀ ਲਿਆਇਆ। ਸਰਦਾਰੇ ਨੇ ਖੁਦ ਅੱਗੇ ਵਧ ਕੇ ਉਹ ਪੌੜੀ ਕਰਤਾਰੇ ਦੇ ਕੋਠੇ ਨਾਲ ਟਿਕਾਈ। ਕਰਤਾਰੇ ਦਾ ਪਰਿਵਾਰ ਹੜਬੜਾਹਟ ਵਿੱਚ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਪੌੜੀ ਰਾਹੀਂ ਹੇਠਾਂ ਉੱਤਰਿਆ। ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਬੱਚਿਆਂ ਨੂੰ ਉਤਾਰਿਆ ਗਿਆ, ਫਿਰ ਔਰਤਾਂ ਅਤੇ ਆਖਰ ਵਿੱਚ ਕਰਤਾਰਾ ਆਪ ਉੱਤਰਿਆ। ਕੁਝ ਹੀ ਮਿੰਟਾਂ ਵਿੱਚ ਉਹ ਸਭ ਸਰਦਾਰੇ ਦੇ ਘਰ ਦੀ ਛੱਤ ਉੱਤੇ ਆ ਗਏ। ਅਜੇ ਉਹ ਸੰਭਲੇ ਵੀ ਨਹੀਂ ਸਨ ਕਿ ਦੂਜਾ ਕਮਰਾ ਵੀ ਧੜੰਮ ਕਰ ਕੇ ਡਿੱਗ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d15e7881-4fec-4202-af7c-d013ff2820ce', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸੇ ਕਮਰੇ ਉੱਤੇ ਕੁਝ ਸਮਾਂ ਪਹਿਲਾਂ ਕਰਤਾਰੇ ਦਾ ਟੱਬਰ ਬੈਠਾ ਸੀ। ਜੇ ਉਹ ਉੱਪਰ ਹੀ ਰਹਿੰਦੇ ਤਾਂ ਜ਼ਰੂਰ ਕੋਈ ਭਾਣਾ ਵਾਪਰ ਜਾਣਾ ਸੀ। ਇਹ ਦੇਖ ਕੇ ਸਾਰਿਆਂ ਦੇ ਮੂੰਹੋਂ ਸ਼ੁਕਰਾਨੇ ਦੇ ਬੋਲ ਨਿਕਲਣ ਲੱਗੇ। ਬਾਹਰ ਮੀਂਹ ਹੋਰ ਤੇਜ਼ ਹੋ ਗਿਆ ਸੀ। ਦੋਵਾਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਵੀ ਹੰਝੂਆਂ ਦੀ ਝੜੀ ਲੱਗੀ ਹੋਈ ਸੀ ਪਰ ਇਹ ਹੰਝੂ ਦੁੱਖ ਦੇ ਨਹੀਂ ਸਨ। ਇਹ ਹੰਝੂ ਰਿਸ਼ਤਿਆਂ ਦੀ ਮੁਹੱਬਤ ਦੇ ਸਨ ਜਿਹੜੇ ਫੋਕੀਆਂ ਰੰਜਸ਼ਾਂ ਤੇ ਰੋਸਿਆਂ ਨੂੰ ਦਿਲਾਂ ਵਿੱਚੋਂ ਹੂੰਝ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('cf7f28c3-e488-47af-bb79-df7e15b2e090', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਰਤਾਰਾ ਭਿੱਜੀਆਂ ਅੱਖਾਂ ਨਾਲ ਸਰਦਾਰੇ ਦੇ ਗਲ ਲੱਗ ਕੇ ਕਹਿਣ ਲੱਗਾ, ''ਭਰਾ, ਮਾਫ਼ ਕਰ ਦੇ। ਅੱਜ ਜੇ ਤੂੰ ਨਾ ਹੁੰਦਾ ਤਾਂ ਸਾਡਾ ਕੀ ਬਣਦਾ!'' ਸਰਦਾਰਾ ਭਰੇ ਮਨ ਨਾਲ ਬੋਲਿਆ, ''ਬਚਾਉਣ ਵਾਲਾ ਤਾਂ ਵਾਹਿਗੁਰੂ ਹੈ ਵੀਰਿਆ। ਜੋ ਹੋਇਆ ਉਹ ਭੁੱਲ ਜਾ। ਅੱਜ ਤੋਂ ਆਪਣਾ ਕੋਈ ਰੋਸਾ ਨਹੀਂ, ਮੈਂ ਹੀ ਗਲਤ ਸਾਂ। ਆਪਣਾ ਸਾਰਾ ਝਗੜਾ ਇਸ ਕਮਰੇ ਦੇ ਨਾਲ ਹੀ ਮੁੱਕ ਗਿਆ ਸਮਝੀਂ।''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5a16eb5e-400d-4b07-a29c-0eda7fd3f1f4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜੇ ਦਿਨ ਤੱਕ ਹਾਲਤ ਹੋਰ ਬਦਤਰ ਹੋ ਚੁੱਕੀ ਸੀ। ਅਚਾਨਕ ਕਰਤਾਰੇ ਦੇ ਘਰੋਂ ਜ਼ੋਰਦਾਰ ਖੜਾਕ ਹੋਇਆ। ਸਾਰਿਆਂ ਦਾ ਧਿਆਨ ਉਸ ਪਾਸੇ ਖਿੱਚਿਆ ਗਿਆ। ਇੱਕ ਕਮਰਾ ਬੁਰੀ ਤਰ੍ਹਾਂ ਢਹਿ ਪਿਆ ਸੀ ਤੇ ਦੂਜਾ ਵੀ ਡਿੱਗਣ ਵਾਲਾ ਸੀ। ਕਰਤਾਰੇ ਦੇ ਪਰਿਵਾਰ ਉੱਤੇ ਡਰ ਦਾ ਸਾਇਆ ਛਾ ਗਿਆ। ਸਭ ਤੋਂ ਵੱਡੀ ਸਮੱਸਿਆ ਇਹ ਸੀ ਕਿ ਜਿਸ ਕਮਰੇ ਤੋਂ ਕੋਠੇ ਉੱਤੇ ਜਾਣ ਵਾਲੀ ਪੌੜੀ ਸੀ, ਉਹ ਵੀ ਢਹਿ ਗਿਆ ਸੀ। ਹੁਣ ਹੇਠਾਂ ਉੱਤਰਨ ਦਾ ਰਸਤਾ ਨਹੀਂ ਬਚਿਆ ਸੀ। ਸਰਦਾਰੇ ਦੇ ਪਰਿਵਾਰ ਨੇ ਜਦੋਂ ਇਹ ਦ੍ਰਿਸ਼ ਦੇਖਿਆ ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਕੰਬ ਗਏ। ਸਾਰਾ ਟੱਬਰ ਵਾਹੋ-ਦਾਹੀ ਕਰਤਾਰੇ ਦੇ ਘਰ ਵੱਲ ਦੌੜਿਆ। ਸਰਦਾਰੇ ਦਾ ਮੁੰਡਾ ਤੁਰੰਤ ਘਰੋਂ ਇੱਕ ਵੱਡੀ ਪੌੜੀ ਲਿਆਇਆ। ਸਰਦਾਰੇ ਨੇ ਖੁਦ ਅੱਗੇ ਵਧ ਕੇ ਉਹ ਪੌੜੀ ਕਰਤਾਰੇ ਦੇ ਕੋਠੇ ਨਾਲ ਟਿਕਾਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('3b4384e1-ff25-437d-9d5e-c613540408cb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਰਤਾਰੇ ਦਾ ਪਰਿਵਾਰ ਹੜਬੜਾਹਟ ਵਿੱਚ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਪੌੜੀ ਰਾਹੀਂ ਹੇਠਾਂ ਉੱਤਰਿਆ। ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਬੱਚਿਆਂ ਨੂੰ ਉਤਾਰਿਆ ਗਿਆ, ਫਿਰ ਔਰਤਾਂ ਅਤੇ ਆਖਰ ਵਿੱਚ ਕਰਤਾਰਾ ਆਪ ਉੱਤਰਿਆ। ਕੁਝ ਹੀ ਮਿੰਟਾਂ ਵਿੱਚ ਉਹ ਸਭ ਸਰਦਾਰੇ ਦੇ ਘਰ ਦੀ ਛੱਤ ਉੱਤੇ ਆ ਗਏ। ਅਜੇ ਉਹ ਸੰਭਲੇ ਵੀ ਨਹੀਂ ਸਨ ਕਿ ਦੂਜਾ ਕਮਰਾ ਵੀ ਧੜੰਮ ਕਰ ਕੇ ਡਿੱਗ ਗਿਆ। ਇਸੇ ਕਮਰੇ ਉੱਤੇ ਕੁਝ ਸਮਾਂ ਪਹਿਲਾਂ ਕਰਤਾਰੇ ਦਾ ਟੱਬਰ ਬੈਠਾ ਸੀ। ਜੇ ਉਹ ਉੱਪਰ ਹੀ ਰਹਿੰਦੇ ਤਾਂ ਜ਼ਰੂਰ ਕੋਈ ਭਾਣਾ ਵਾਪਰ ਜਾਣਾ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
