  ('46fdc0d7-069a-46d4-9ca5-4495ccb2880f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਰਦਾਰਾ ਭਰੇ ਮਨ ਨਾਲ ਬੋਲਿਆ, ''ਬਚਾਉਣ ਵਾਲਾ ਤਾਂ ਵਾਹਿਗੁਰੂ ਹੈ ਵੀਰਿਆ। ਜੋ ਹੋਇਆ ਉਹ ਭੁੱਲ ਜਾ। ਅੱਜ ਤੋਂ ਆਪਣਾ ਕੋਈ ਰੋਸਾ ਨਹੀਂ, ਮੈਂ ਹੀ ਗਲਤ ਸਾਂ। ਆਪਣਾ ਸਾਰਾ ਝਗੜਾ ਇਸ ਕਮਰੇ ਦੇ ਨਾਲ ਹੀ ਮੁੱਕ ਗਿਆ ਸਮਝੀਂ।''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8b50c33c-0c58-4ee0-8295-accd07a12a33', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜੇ ਦਿਨ ਤੱਕ ਹਾਲਤ ਹੋਰ ਬਦਤਰ ਹੋ ਚੁੱਕੀ ਸੀ। ਅਚਾਨਕ ਕਰਤਾਰੇ ਦੇ ਘਰੋਂ ਜ਼ੋਰਦਾਰ ਖੜਾਕ ਹੋਇਆ। ਸਾਰਿਆਂ ਦਾ ਧਿਆਨ ਉਸ ਪਾਸੇ ਖਿੱਚਿਆ ਗਿਆ। ਇੱਕ ਕਮਰਾ ਬੁਰੀ ਤਰ੍ਹਾਂ ਢਹਿ ਪਿਆ ਸੀ ਤੇ ਦੂਜਾ ਵੀ ਡਿੱਗਣ ਵਾਲਾ ਸੀ। ਕਰਤਾਰੇ ਦੇ ਪਰਿਵਾਰ ਉੱਤੇ ਡਰ ਦਾ ਸਾਇਆ ਛਾ ਗਿਆ। ਸਭ ਤੋਂ ਵੱਡੀ ਸਮੱਸਿਆ ਇਹ ਸੀ ਕਿ ਜਿਸ ਕਮਰੇ ਤੋਂ ਕੋਠੇ ਉੱਤੇ ਜਾਣ ਵਾਲੀ ਪੌੜੀ ਸੀ, ਉਹ ਵੀ ਢਹਿ ਗਿਆ ਸੀ। ਹੁਣ ਹੇਠਾਂ ਉੱਤਰਨ ਦਾ ਰਸਤਾ ਨਹੀਂ ਬਚਿਆ ਸੀ। ਸਰਦਾਰੇ ਦੇ ਪਰਿਵਾਰ ਨੇ ਜਦੋਂ ਇਹ ਦ੍ਰਿਸ਼ ਦੇਖਿਆ ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਕੰਬ ਗਏ। ਸਾਰਾ ਟੱਬਰ ਵਾਹੋ-ਦਾਹੀ ਕਰਤਾਰੇ ਦੇ ਘਰ ਵੱਲ ਦੌੜਿਆ। ਸਰਦਾਰੇ ਦਾ ਮੁੰਡਾ ਤੁਰੰਤ ਘਰੋਂ ਇੱਕ ਵੱਡੀ ਪੌੜੀ ਲਿਆਇਆ। ਸਰਦਾਰੇ ਨੇ ਖੁਦ ਅੱਗੇ ਵਧ ਕੇ ਉਹ ਪੌੜੀ ਕਰਤਾਰੇ ਦੇ ਕੋਠੇ ਨਾਲ ਟਿਕਾਈ। ਕਰਤਾਰੇ ਦਾ ਪਰਿਵਾਰ ਹੜਬੜਾਹਟ ਵਿੱਚ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਪੌੜੀ ਰਾਹੀਂ ਹੇਠਾਂ ਉੱਤਰਿਆ। ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਬੱਚਿਆਂ ਨੂੰ ਉਤਾਰਿਆ ਗਿਆ, ਫਿਰ ਔਰਤਾਂ ਅਤੇ ਆਖਰ ਵਿੱਚ ਕਰਤਾਰਾ ਆਪ ਉੱਤਰਿਆ। ਕੁਝ ਹੀ ਮਿੰਟਾਂ ਵਿੱਚ ਉਹ ਸਭ ਸਰਦਾਰੇ ਦੇ ਘਰ ਦੀ ਛੱਤ ਉੱਤੇ ਆ ਗਏ। ਅਜੇ ਉਹ ਸੰਭਲੇ ਵੀ ਨਹੀਂ ਸਨ ਕਿ ਦੂਜਾ ਕਮਰਾ ਵੀ ਧੜੰਮ ਕਰ ਕੇ ਡਿੱਗ ਗਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('83ec12cc-87c5-45c3-a101-db64898674db', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸੇ ਕਮਰੇ ਉੱਤੇ ਕੁਝ ਸਮਾਂ ਪਹਿਲਾਂ ਕਰਤਾਰੇ ਦਾ ਟੱਬਰ ਬੈਠਾ ਸੀ। ਜੇ ਉਹ ਉੱਪਰ ਹੀ ਰਹਿੰਦੇ ਤਾਂ ਜ਼ਰੂਰ ਕੋਈ ਭਾਣਾ ਵਾਪਰ ਜਾਣਾ ਸੀ। ਇਹ ਦੇਖ ਕੇ ਸਾਰਿਆਂ ਦੇ ਮੂੰਹੋਂ ਸ਼ੁਕਰਾਨੇ ਦੇ ਬੋਲ ਨਿਕਲਣ ਲੱਗੇ। ਬਾਹਰ ਮੀਂਹ ਹੋਰ ਤੇਜ਼ ਹੋ ਗਿਆ ਸੀ। ਦੋਵਾਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਵੀ ਹੰਝੂਆਂ ਦੀ ਝੜੀ ਲੱਗੀ ਹੋਈ ਸੀ ਪਰ ਇਹ ਹੰਝੂ ਦੁੱਖ ਦੇ ਨਹੀਂ ਸਨ। ਇਹ ਹੰਝੂ ਰਿਸ਼ਤਿਆਂ ਦੀ ਮੁਹੱਬਤ ਦੇ ਸਨ ਜਿਹੜੇ ਫੋਕੀਆਂ ਰੰਜਸ਼ਾਂ ਤੇ ਰੋਸਿਆਂ ਨੂੰ ਦਿਲਾਂ ਵਿੱਚੋਂ ਹੂੰਝ ਰਹੇ ਸਨ। ਕਰਤਾਰਾ ਭਿੱਜੀਆਂ ਅੱਖਾਂ ਨਾਲ ਸਰਦਾਰੇ ਦੇ ਗਲ ਲੱਗ ਕੇ ਕਹਿਣ ਲੱਗਾ, ''ਭਰਾ, ਮਾਫ਼ ਕਰ ਦੇ। ਅੱਜ ਜੇ ਤੂੰ ਨਾ ਹੁੰਦਾ ਤਾਂ ਸਾਡਾ ਕੀ ਬਣਦਾ!'' ਸਰਦਾਰਾ ਭਰੇ ਮਨ ਨਾਲ ਬੋਲਿਆ, ''ਬਚਾਉਣ ਵਾਲਾ ਤਾਂ ਵਾਹਿਗੁਰੂ ਹੈ ਵੀਰਿਆ। ਜੋ ਹੋਇਆ ਉਹ ਭੁੱਲ ਜਾ। ਅੱਜ ਤੋਂ ਆਪਣਾ ਕੋਈ ਰੋਸਾ ਨਹੀਂ, ਮੈਂ ਹੀ ਗਲਤ ਸਾਂ। ਆਪਣਾ ਸਾਰਾ ਝਗੜਾ ਇਸ ਕਮਰੇ ਦੇ ਨਾਲ ਹੀ ਮੁੱਕ ਗਿਆ ਸਮਝੀਂ।''$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('33e8b618-0ba5-4d19-b320-38bd1aaecd02', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਬੀਬੀਆਂ ਵੀ ਸਿੱਲ੍ਹੀਆਂ ਅੱਖਾਂ ਨਾਲ ਇੱਕ-ਦੂਜੀ ਨੂੰ ਗਲ ਲਾ ਰਹੀਆਂ ਸਨ। ਹੜ੍ਹਾਂ ਨੇ ਭਾਵੀਂ ਘਰ-ਬਾਰ ਤਬਾਹ ਕਰ ਦਿੱਤੇ ਸਨ ਪਰ ਰਿਸ਼ਤਿਆਂ ਦੇ ਰੇਸ਼ਮੀ ਧਾਗੇ ਹੋਰ ਮਜ਼ਬੂਤ ਹੋ ਗਏ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c7d284ab-3ed2-4532-be97-d57e07cb0e32', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੜ੍ਹਾਂ ਦੇ ਨਾਲ ਹੀ ਰੋਸੇ, ਗਿਲੇ, ਈਰਖਾ ਤੇ ਦੁਸ਼ਮਣੀਆਂ ਵਹਿ ਗਈਆਂ ਸਨ ਅਤੇ ਇਸ ਦੀ ਥਾਂ ਮੋਹ-ਮੁਹੱਬਤ ਤੇ ਭਾਈਚਾਰੇ ਦੀ ਚਮਕ ਤੇਜ਼ ਹੋ ਗਈ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('00137663-3bfd-4590-9a6f-a0480ad5daad', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$* ਰਿਸ਼ਤਿਆਂ ਦੇ ਮਹੱਤਵ ਤੋਂ ਜਾਣੂ ਹੋਣਾ। * ਮੁਸੀਬਤ ਵਿੱਚ ਇੱਕ-ਦੂਜੇ ਦੀ ਮਦਦ ਕਰਨ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਹੋਣਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('6bd74e94-14b8-4ad8-95cc-65e617482902', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ— (ੳ) ਕਿਸੇ ਬਿਪਤਾ ਦੇ ਸਮੇਂ ਲੋਕਾਂ ਨੂੰ ਇੱਕ-ਦੂਜੇ ਦੀ ਮਦਦ ਕਿਉਂ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ? (ਅ) ਕੀ ਤੁਸੀਂ ਆਪਣੇ ਪਿੰਡ/ਸ਼ਹਿਰ ਵਿੱਚ ਕੋਈ ਹੜ੍ਹ ਜਾਂ ਕੁਦਰਤੀ ਆਫ਼ਤ ਦੇਖੀ ਹੈ? (ੲ) ਰਿਸ਼ਤੇ ਬਚਾਉਣ ਲਈ ਸਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7dd1659c-f360-4bd1-b5e3-f97b990dae79', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਬੀਬੀਆਂ ਵੀ ਸਿੱਲ੍ਹੀਆਂ ਅੱਖਾਂ ਨਾਲ ਇੱਕ-ਦੂਜੀ ਨੂੰ ਗਲ ਲਾ ਰਹੀਆਂ ਸਨ। ਹੜ੍ਹਾਂ ਨੇ ਭਾਵੀਂ ਘਰ-ਬਾਰ ਤਬਾਹ ਕਰ ਦਿੱਤੇ ਸਨ ਪਰ ਰਿਸ਼ਤਿਆਂ ਦੇ ਰੇਸ਼ਮੀ ਧਾਗੇ ਹੋਰ ਮਜ਼ਬੂਤ ਹੋ ਗਏ ਸਨ। ਹੜ੍ਹਾਂ ਦੇ ਨਾਲ ਹੀ ਰੋਸੇ, ਗਿਲੇ, ਈਰਖਾ ਤੇ ਦੁਸ਼ਮਣੀਆਂ ਵਹਿ ਗਈਆਂ ਸਨ ਅਤੇ ਇਸ ਦੀ ਥਾਂ ਮੋਹ-ਮੁਹੱਬਤ ਤੇ ਭਾਈਚਾਰੇ ਦੀ ਚਮਕ ਤੇਜ਼ ਹੋ ਗਈ ਸੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1bd667bb-b646-4c37-9026-4bcba07e9cd6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ਾਮ ਦਾ ਵੇਲਾ ਸੀ। ਅਸਮਾਨ ਕਾਲੇ ਬੱਦਲਾਂ ਨਾਲ ਕੱਜਿਆ ਹੋਇਆ ਸੀ। ਗੁਰੂ ਘਰੋਂ ਸਪੀਕਰ ਉੱਤੇ ਆਈ ਅਵਾਜ਼ ਨੇ ਸਾਰੇ ਪਿੰਡ ਵਾਸੀਆਂ ਨੂੰ ਫਿਕਰਾਂ ਵਿੱਚ ਪਾ ਦਿੱਤਾ। ਪਾਠੀ ਸਿੰਘ ਨੇ ਪਿੰਡ ਵਾਸੀਆਂ ਨੂੰ ਹੜ੍ਹਾਂ ਬਾਰੇ ਸੁਚੇਤ ਕਰਦਿਆਂ ਕਿਹਾ, ÒÒਪ੍ਰਸ਼ਾਸਨ ਦਾ ਸੁਨੇਹਾ ਆਇਆ ਹੈ ਕਿ ਤੁਰੰਤ ਪਿੰਡ ਛੱਡ ਕੇ ਸੁਰੱਖਿਅਤ ਥਾਵਾਂ ਉੱਤੇ ਚਲੇ ਜਾਓ। ਦਰਿਆ ਵਿੱਚ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਹੈ, ਸਾਵਧਾਨ ਰਹੋ।ÓÓ ਇਹ ਸੁਣ ਕੇ ਲੋਕਾਂ ਵਿੱਚ ਘੁਸਰ-ਮੁਸਰ ਹੋਣ ਲੱਗੀ। ਵੈਸੇ ਤਾਂ ਪਿਛਲੇ ਕਈ ਦਿਨਾਂ ਤੋਂ ਬੇਮੌਸਮੇ ਮੀਂਹ ਨੇ ਲੋਕਾਂ ਦੇ ਸਾਹ ਸੂਤੇ ਹੋਏ ਸਨ ਪਰ ਹੜ੍ਹਾਂ ਬਾਰੇ ਕਿਸੇ ਨੇ ਬਹੁਤੀ ਚਿੰਤਾ ਨਹੀਂ ਕੀਤੀ ਸੀ। ਇਹ ਪਿੰਡ ਸਤਲੁਜ ਦਰਿਆ ਦੇ ਬਿਲਕੁਲ ਨੇੜੇ ਸੀ। ਪਹਾੜੀ ਖੇਤਰਾਂ ਵਿੱਚ ਵੀ ਹਾਲਾਤ ਸੁਖਾਵੇਂ ਨਹੀਂ ਸਨ। ਡੈਮਾਂ ਵਿੱਚ ਪਾਣੀ ਦਾ ਪੱਧਰ ਵੱਧ ਰਿਹਾ ਸੀ। ਹੁਣ ਜਦੋਂ ਡੈਮ ਵਿੱਚੋਂ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਤਾਂ ਹੜ੍ਹਾਂ ਦਾ ਖ਼ਤਰਾ ਹਕੀਕਤ ਬਣ ਗਿਆ ਸੀ। ਇਹ ਪਿੰਡ ਬਸੰਤਪੁਰ ਸੀ - ਨਾਂ ਵਾਂਗ ਹੀ ਸੋਹਣਾ। ਹਰਿਆਲੀ, ਖੇਤਾਂ ਵਿੱਚ ਲਹਿਲਹਾਉਂਦੀਆਂ ਫਸਲਾਂ, ਖੁੱਲ੍ਹੇ ਵਿਹੜਿਆਂ ਵਾਲੇ ਘਰ, ਗਲੀਆਂ ਵਿੱਚ ਕਿਲਕਾੜੀਆਂ ਮਾਰਦੇ ਬੱਚੇ ਤੇ ਸੱਥ ਵਿੱਚ ਬਾਬਿਆਂ ਦੀਆਂ ਗੱਲਾਂ - ਇਹ ਸਭ ਬਸੰਤਪੁਰ ਨੂੰ ਨਿਆਰੀ ਦਿੱਖ ਬਖਸ਼ਦਾ ਸੀ ਪਰ ਅੱਜ ਇਹ ਪਿੰਡ ਗੰਭੀਰ ਬਿਪਤਾ ਨਾਲ ਦੋ-ਚਾਰ ਹੋਣ ਜਾ ਰਿਹਾ ਸੀ। ਅਨਾਊਂਸਮੈਂਟ ਸੁਣਦਿਆਂ ਹੀ ਲੋਕਾਂ ਨੇ ਹੱਥਲੇ ਕੰਮ ਰੋਕ ਦਿੱਤੇ। ਉਹਨਾਂ ਨੇ ਆਪਣੀਆਂ ਕੀਮਤੀ ਵਸਤਾਂ ਇਕੱਠੀਆਂ ਕਰਨੀਆਂ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੀਆਂ-ਜ਼ਰੂਰੀ ਕਾਗਜ਼-ਪੱਤਰ, ਨਕਦੀ, ਮੋਬਾਈਲ ਤੇ ਕੁਝ ਸੁੱਕਾ ਰਾਸ਼ਨ। ਸਭ ਤੋਂ ਵੱਡੀ ਅੌਖੀ ਘੜੀ ਕਿਸਾਨਾਂ ਲਈ ਡੰਗਰਾਂ ਦੀ ਸੀ। ਇਹਨਾਂ ਨੂੰ ਛੱਡਣਾ ਵੀ ਸੰਭਵ ਨਹੀਂ ਸੀ ਤੇ ਨਾਲ ਲਿਜਾਣਾ ਵੀ ਮੁਸ਼ਕਲ ਸੀ। ਕਈਆਂ ਨੇ ਰੱਸੇ ਖੋਲ੍ਹ ਦਿੱਤੇ ਕਿ ਜਾਨਵਰ ਆਪਣੇ-ਆਪ ਬਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰ ਲੈਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c475c9fc-28b5-41a0-a39e-47d9f5eb9dbb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ਾਮ ਦਾ ਵੇਲਾ ਸੀ। ਅਸਮਾਨ ਕਾਲੇ ਬੱਦਲਾਂ ਨਾਲ ਕੱਜਿਆ ਹੋਇਆ ਸੀ। ਗੁਰੂ ਘਰੋਂ ਸਪੀਕਰ ਉੱਤੇ ਆਈ ਅਵਾਜ਼ ਨੇ ਸਾਰੇ ਪਿੰਡ ਵਾਸੀਆਂ ਨੂੰ ਫਿਕਰਾਂ ਵਿੱਚ ਪਾ ਦਿੱਤਾ। ਪਾਠੀ ਸਿੰਘ ਨੇ ਪਿੰਡ ਵਾਸੀਆਂ ਨੂੰ ਹੜ੍ਹਾਂ ਬਾਰੇ ਸੁਚੇਤ ਕਰਦਿਆਂ ਕਿਹਾ, ÒÒਪ੍ਰਸ਼ਾਸਨ ਦਾ ਸੁਨੇਹਾ ਆਇਆ ਹੈ ਕਿ ਤੁਰੰਤ ਪਿੰਡ ਛੱਡ ਕੇ ਸੁਰੱਖਿਅਤ ਥਾਵਾਂ ਉੱਤੇ ਚਲੇ ਜਾਓ। ਦਰਿਆ ਵਿੱਚ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਹੈ, ਸਾਵਧਾਨ ਰਹੋ।ÓÓ ਇਹ ਸੁਣ ਕੇ ਲੋਕਾਂ ਵਿੱਚ ਘੁਸਰ-ਮੁਸਰ ਹੋਣ ਲੱਗੀ। ਵੈਸੇ ਤਾਂ ਪਿਛਲੇ ਕਈ ਦਿਨਾਂ ਤੋਂ ਬੇਮੌਸਮੇ ਮੀਂਹ ਨੇ ਲੋਕਾਂ ਦੇ ਸਾਹ ਸੂਤੇ ਹੋਏ ਸਨ ਪਰ ਹੜ੍ਹਾਂ ਬਾਰੇ ਕਿਸੇ ਨੇ ਬਹੁਤੀ ਚਿੰਤਾ ਨਹੀਂ ਕੀਤੀ ਸੀ। ਇਹ ਪਿੰਡ ਸਤਲੁਜ ਦਰਿਆ ਦੇ ਬਿਲਕੁਲ ਨੇੜੇ ਸੀ। ਪਹਾੜੀ ਖੇਤਰਾਂ ਵਿੱਚ ਵੀ ਹਾਲਾਤ ਸੁਖਾਵੇਂ ਨਹੀਂ ਸਨ। ਡੈਮਾਂ ਵਿੱਚ ਪਾਣੀ ਦਾ ਪੱਧਰ ਵੱਧ ਰਿਹਾ ਸੀ। ਹੁਣ ਜਦੋਂ ਡੈਮ ਵਿੱਚੋਂ ਪਾਣੀ ਛੱਡਿਆ ਗਿਆ ਤਾਂ ਹੜ੍ਹਾਂ ਦਾ ਖ਼ਤਰਾ ਹਕੀਕਤ ਬਣ ਗਿਆ ਸੀ। ਇਹ ਪਿੰਡ ਬਸੰਤਪੁਰ ਸੀ - ਨਾਂ ਵਾਂਗ ਹੀ ਸੋਹਣਾ। ਹਰਿਆਲੀ, ਖੇਤਾਂ ਵਿੱਚ ਲਹਿਲਹਾਉਂਦੀਆਂ ਫਸਲਾਂ, ਖੁੱਲ੍ਹੇ ਵਿਹੜਿਆਂ ਵਾਲੇ ਘਰ, ਗਲੀਆਂ ਵਿੱਚ ਕਿਲਕਾੜੀਆਂ ਮਾਰਦੇ ਬੱਚੇ ਤੇ ਸੱਥ ਵਿੱਚ ਬਾਬਿਆਂ ਦੀਆਂ ਗੱਲਾਂ - ਇਹ ਸਭ ਬਸੰਤਪੁਰ ਨੂੰ ਨਿਆਰੀ ਦਿੱਖ ਬਖਸ਼ਦਾ ਸੀ ਪਰ ਅੱਜ ਇਹ ਪਿੰਡ ਗੰਭੀਰ ਬਿਪਤਾ ਨਾਲ ਦੋ-ਚਾਰ ਹੋਣ ਜਾ ਰਿਹਾ ਸੀ। ਅਨਾਊਂਸਮੈਂਟ ਸੁਣਦਿਆਂ ਹੀ ਲੋਕਾਂ ਨੇ ਹੱਥਲੇ ਕੰਮ ਰੋਕ ਦਿੱਤੇ। ਉਹਨਾਂ ਨੇ ਆਪਣੀਆਂ ਕੀਮਤੀ ਵਸਤਾਂ ਇਕੱਠੀਆਂ ਕਰਨੀਆਂ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤੀਆਂ-ਜ਼ਰੂਰੀ ਕਾਗਜ਼-ਪੱਤਰ, ਨਕਦੀ, ਮੋਬਾਈਲ ਤੇ ਕੁਝ ਸੁੱਕਾ ਰਾਸ਼ਨ। ਸਭ ਤੋਂ ਵੱਡੀ ਅੌਖੀ ਘੜੀ ਕਿਸਾਨਾਂ ਲਈ ਡੰਗਰਾਂ ਦੀ ਸੀ। ਇਹਨਾਂ ਨੂੰ ਛੱਡਣਾ ਵੀ ਸੰਭਵ ਨਹੀਂ ਸੀ ਤੇ ਨਾਲ ਲਿਜਾਣਾ ਵੀ ਮੁਸ਼ਕਲ ਸੀ। ਕਈਆਂ ਨੇ ਰੱਸੇ ਖੋਲ੍ਹ ਦਿੱਤੇ ਕਿ ਜਾਨਵਰ ਆਪਣੇ-ਆਪ ਬਚਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰ ਲੈਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
