  ('acdafbd8-b535-4dfc-b70e-a390c6ab9fd4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਘਰਾਂ ਨੇ ਬੱਕਰਿਆਂ, ਗਾਵਾਂ ਅਤੇ ਮੱਝਾਂ ਨੂੰ ਉੱਚੀਆਂ ਥਾਵਾਂ ਵੱਲ ਛੱਡ ਦਿੱਤਾ। ਕਈ ਪਰਿਵਾਰ ਔਰਤਾਂ ਤੇ ਬੱਚਿਆਂ ਨੂੰ ਲੈ ਕੇ ਪਿੰਡ ਤੋਂ ਬਾਹਰ ਜਾਣ ਲੱਗੇ ਪਰ ਅਜੇ ਵੀ ਕਈਆਂ ਨੂੰ ਯਕੀਨ ਨਹੀਂ ਸੀ ਕਿ ਪਾਣੀ ਇੱਥੇ ਤੱਕ ਪਹੁੰਚ ਸਕਦਾ ਹੈ। ਸਵੇਰ ਹੁੰਦਿਆਂ ਹੀ ਪਿੰਡ ਦਾ ਦ੍ਰਿਸ਼ ਪੂਰੀ ਤਰ੍ਹਾਂ ਬਦਲ ਗਿਆ। ਜਿਸ ਥਾਂ ਕਦੇ ਸੁਨਹਿਰੀ ਝੋਨੇ ਦੀ ਫਸਲ ਖੜ੍ਹੀ ਸੀ, ਉੱਥੇ ਹੁਣ ਸਿਰਫ਼ ਪਾਣੀ ਹੀ ਪਾਣੀ ਸੀ। ਲੱਗਦਾ ਸੀ ਜਿਵੇਂ ਪਿੰਡ ਸਮੁੰਦਰ ਵਿੱਚ ਬਦਲ ਗਿਆ ਹੋਵੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('45517d8d-5ce3-4fc9-b937-e4f4efdfa983', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਘਰਾਂ ਦੇ ਆਹਮਣੇ-ਦੁਆਲ੍ਹੇ ਪਾਣੀ ਵਗ ਰਿਹਾ ਸੀ, ਨੀਵੇਂ ਘਰਾਂ ਦੀਆਂ ਤਾਂ ਬੱਸ ਛੱਤਾਂ ਹੀ ਨਜ਼ਰ ਆਉਂਦੀਆਂ ਸਨ। ਕਈ ਲੋਕਾਂ ਨੇ ਆਪਣੇ ਘਰਾਂ ਦੀਆਂ ਛੱਤਾਂ ਉੱਤੇ ਝੁੱਗੀਆਂ ਬਣਾ ਲਈਆਂ। ਹੁਣ ਇਹ ਝੁੱਗੀਆਂ ਹੀ ਆਰਜ਼ੀ ਆਸਰਾ ਸਨ। ਇਹਨਾਂ ਵਿੱਚ ਹੀ ਚੁੱਲ੍ਹਾ-ਚੌਂਕਾ ਤੇ ਇਹਨਾਂ ਵਿੱਚ ਹੀ ਬਹਿਣ-ਪੈਣ ਦਾ ਇੰਤਜ਼ਾਮ ਹੋ ਰਿਹਾ ਸੀ। ਉੱਧਰੋਂ ਇੰਦਰ ਦੇਵਤਾ ਵੀ ਲਗਾਤਾਰ ਲੋਕਾਂ ਦੇ ਸਬਰ ਦਾ ਇਮਤਿਹਾਨ ਲੈ ਰਿਹਾ ਸੀ। ਲੋਕ ਇੱਕ-ਦੂਜੇ ਨੂੰ ਦਿਲਾਸਾ ਦਿੰਦੇ ਮਦਦ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('083001ce-9d41-407d-bad6-cdfef2232171', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਿੰਡ ਵਿੱਚ ਕਰਤਾਰਾ ਤੇ ਸਰਦਾਰਾ ਦੋਵੇਂ ਮੰਨੇ-ਪ੍ਰਮੰਨੇ ਕਿਸਾਨ ਸਨ। ਦੋਵਾਂ ਨੇ ਥੋੜ੍ਹੀ-ਜਿਹੀ ਜ਼ਮੀਨ ਵਿੱਚੋਂ ਵੀ ਭਰਵੀਆਂ ਫਸਲਾਂ ਲੈ ਕੇ ਆਪਣੇ ਘਰਾਂ ਨੂੰ ਪੈਰਾਂ-ਸਿਰ ਕੀਤਾ ਹੋਇਆ ਸੀ। ਭਾਵੇਂ ਦੋਵੇਂ ਚਾਚੇ-ਤਾਏ ਦੇ ਪੁੱਤਰ ਸਨ ਪਰ ਆਪਸੀ ਬੋਲ-ਬਾਣੀ ਬੰਦ ਸੀ। ਪਿਛਲੇ ਸਾਲ ਇੱਕ ਵੱਟ ਦੇ ਰੌਲੇ ਤੋਂ ਸ਼ੁਰੂ ਹੋਈ ਗੱਲ ਕੋਰਟ-ਕਚਹਿਰੀ ਤੱਕ ਪਹੁੰਚ ਗਈ ਸੀ। ਉਸ ਦਿਨ ਤੋਂ ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਨੇ ਇੱਕ-ਦੂਜੇ ਨੂੰ ਬੁਲਾਉਣਾ ਛੱਡ ਦਿੱਤਾ ਸੀ। ਦੋਵਾਂ ਦੇ ਸਾਂਝੇ ਰਿਸ਼ਤੇਦਾਰਾਂ ਨੇ ਸਮਝਾਉਣ ਦੀ ਬੜੀ ਕੋਸ਼ਿਸ਼ ਕੀਤੀ ਪਰ ਦੋਵੇਂ ਧੀਰਾਂ ਟੱਸ ਤੋਂ ਮੱਸ ਨਹੀਂ ਹੋ ਰਹੀਆਂ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c4d36e07-fe5d-4754-a637-09534f3cd708', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੋਈ ਸਮਾਂ ਸੀ, ਜਦੋਂ ਦੋਵੇਂ ਪਰਿਵਾਰ ਰਲ-ਮਿਲ ਕੇ ਤਿਉਹਾਰ ਮਨਾਉਂਦੇ ਸਨ ਪਰ ਹੁਣ ਰੰਜਸ਼ਾਂ ਦੀਆਂ ਕੰਧਾਂ ਨੇ ਇਹ ਸਾਰਾ ਕੁਝ ਤੋੜ ਦਿੱਤਾ ਸੀ। ਹੁਣ ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੇ ਘਰ ਆਹਮੋ-ਸਾਹਮਣੇ ਸਨ ਤੇ ਹੜ੍ਹ ਦੇ ਪਾਣੀ ਵਿੱਚ ਘਿਰੇ ਹੋਏ ਸਨ। ਦੋਵਾਂ ਨੇ ਆਪਣੇ ਕੋਠਿਆਂ ਉੱਤੇ ਪਲਾਸਟਿਕ ਦੀਆਂ ਤਰਪਾਲਾਂ ਤਾਣ ਕੇ ਝੁੱਗੀਆਂ ਬਣਾ ਲਈਆਂ। ਰਾਤੀਂ ਪਾਣੀ ਦੀ ਗੜਗੜਾਹਟ ਅਤੇ ਮੀਂਹ ਦੀਆਂ ਬੂੰਦਾਂ ਲੋਕਾਂ ਦੇ ਦਿਲਾਂ ਵਿੱਚ ਹੋਰ ਵੀ ਡਰ ਪੈਦਾ ਕਰ ਰਹੀਆਂ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ff73f21e-e9a6-4033-afe9-03cf3561e5d0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਰਤਾਰੇ ਦਾ ਘਰ ਪੁਰਾਣਾ ਸੀ। ਪਾਣੀ ਦੇ ਕਾਰਨ ਕੰਧਾਂ ਕਮਜ਼ੋਰ ਹੋ ਰਹੀਆਂ ਸਨ। ਸਰਦਾਰੇ ਦਾ ਘਰ ਨਵਾਂ ਸੀ ਤੇ ਕੁਝ ਮਜ਼ਬੂਤ ਲੱਗ ਰਿਹਾ ਸੀ। ਫਿਰ ਵੀ ਦੋਵੇਂ ਪਰਿਵਾਰ ਕੋਠਿਆਂ ਉੱਤੇ ਬੈਠੇ ਇੱਕ-ਦੂਜੇ ਵੱਲ ਚੋਰੀ-ਚੋਰੀ ਤੱਕ ਲੈਂਦੇ। ਭਾਵੇਂ ਸਰਦਾਰਾ ਕਰਤਾਰੇ ਨਾਲ ਬੋਲਦਾ ਨਹੀਂ ਸੀ ਪਰ ਉਸਦੇ ਘਰ ਦਾ ਫਿਕਰ ਉਸਨੂੰ ਵੀ ਬਹੁਤ ਸੀ। ਉਹ ਆਪਣੇ ਟੱਬਰ ਨੂੰ ਕਹਿੰਦਾ, 'ਕਰਤਾਰੇ ਦਾ ਘਰ ਡਿੱਗੂ-ਡਿੱਗੂ ਕਰਦੈ। ਇਹਨੂੰ ਛੱਡ ਕੇ ਚਲੇ ਜਾਣਾ ਚਾਹੀਦੈ, ਰੱਬ ਨਾ ਕਰੇ ਜੇ ਇਹ ਡਿੱਗ ਪਿਆ ਤਾਂ ਬੜਾ ਨੁਕਸਾਨ ਹੋ ਜਾਣਾ।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('80faec84-9045-4b3a-a328-6d0ea29602c6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੀਜੇ ਦਿਨ ਤੱਕ ਹਾਲਤ ਹੋਰ ਬਦਤਰ ਹੋ ਚੁੱਕੀ ਸੀ। ਅਚਾਨਕ ਕਰਤਾਰੇ ਦੇ ਘਰੋਂ ਜ਼ੋਰਦਾਰ ਖੜਾਕ ਹੋਇਆ। ਸਾਰਿਆਂ ਦਾ ਧਿਆਨ ਉਸ ਪਾਸੇ ਖਿੱਚਿਆ ਗਿਆ। ਇੱਕ ਕਮਰਾ ਬੁਰੀ ਤਰ੍ਹਾਂ ਢਹਿ ਪਿਆ ਸੀ ਤੇ ਦੂਜਾ ਵੀ ਡਿੱਗਣ ਵਾਲਾ ਸੀ। ਕਰਤਾਰੇ ਦੇ ਪਰਿਵਾਰ ਉੱਤੇ ਡਰ ਦਾ ਸਾਇਆ ਛਾ ਗਿਆ। ਸਭ ਤੋਂ ਵੱਡੀ ਸਮੱਸਿਆ ਇਹ ਸੀ ਕਿ ਜਿਸ ਕਮਰੇ ਤੋਂ ਕੋਠੇ ਉੱਤੇ ਜਾਣ ਵਾਲੀ ਪੌੜੀ ਸੀ, ਉਹ ਵੀ ਢਹਿ ਗਿਆ ਸੀ। ਹੁਣ ਹੇਠਾਂ ਉੱਤਰਨ ਦਾ ਰਸਤਾ ਨਹੀਂ ਬਚਿਆ ਸੀ। ਸਰਦਾਰੇ ਦੇ ਪਰਿਵਾਰ ਨੇ ਜਦੋਂ ਇਹ ਦ੍ਰਿਸ਼ ਦੇਖਿਆ ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਕੰਬ ਗਏ। ਸਾਰਾ ਟੱਬਰ ਵਾਹੋ-ਦਾਹੀ ਕਰਤਾਰੇ ਦੇ ਘਰ ਵੱਲ ਦੌੜਿਆ। ਸਰਦਾਰੇ ਦਾ ਮੁੰਡਾ ਤੁਰੰਤ ਘਰੋਂ ਇੱਕ ਵੱਡੀ ਪੌੜੀ ਲਿਆਇਆ। ਸਰਦਾਰੇ ਨੇ ਖੁਦ ਅੱਗੇ ਵਧ ਕੇ ਉਹ ਪੌੜੀ ਕਰਤਾਰੇ ਦੇ ਕੋਠੇ ਨਾਲ ਟਿਕਾਈ। ਕਰਤਾਰੇ ਦਾ ਪਰਿਵਾਰ ਹੜਬੜਾਹਟ ਵਿੱਚ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਪੌੜੀ ਰਾਹੀਂ ਹੇਠਾਂ ਉੱਤਰਿਆ। ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਬੱਚਿਆਂ ਨੂੰ ਉਤਾਰਿਆ ਗਿਆ, ਫਿਰ ਔਰਤਾਂ ਅਤੇ ਆਖਰ ਵਿੱਚ ਕਰਤਾਰਾ ਆਪ ਉੱਤਰਿਆ। ਕੁਝ ਹੀ ਮਿੰਟਾਂ ਵਿੱਚ ਉਹ ਸਭ ਸਰਦਾਰੇ ਦੇ ਘਰ ਦੀ ਛੱਤ ਉੱਤੇ ਆ ਗਏ। ਅਜੇ ਉਹ ਸੰਭਲੇ ਵੀ ਨਹੀਂ ਸਨ ਕਿ ਦੂਜਾ ਕਮਰਾ ਵੀ ਧੜੰਮ ਕਰ ਕੇ ਡਿੱਗ ਗਿਆ। ਇਸੇ ਕਮਰੇ ਉੱਤੇ ਕੁਝ ਸਮਾਂ ਪਹਿਲਾਂ ਕਰਤਾਰੇ ਦਾ ਟੱਬਰ ਬੈਠਾ ਸੀ। ਜੇ ਉਹ ਉੱਪਰ ਹੀ ਰਹਿੰਦੇ ਤਾਂ ਜ਼ਰੂਰ ਕੋਈ ਭਾਣਾ ਵਾਪਰ ਜਾਣਾ ਸੀ। ਇਹ ਦੇਖ ਕੇ ਸਾਰਿਆਂ ਦੇ ਮੂੰਹੋਂ ਸ਼ੁਕਰਾਨੇ ਦੇ ਬੋਲ ਨਿਕਲਣ ਲੱਗੇ। ਬਾਹਰ ਮੀਂਹ ਹੋਰ ਤੇਜ਼ ਹੋ ਗਿਆ ਸੀ। ਦੋਵਾਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਵੀ ਹੰਝੂਆਂ ਦੀ ਝੜੀ ਲੱਗੀ ਹੋਈ ਸੀ ਪਰ ਇਹ ਹੰਝੂ ਦੁੱਖ ਦੇ ਨਹੀਂ ਸਨ। ਇਹ ਹੰਝੂ ਰਿਸ਼ਤਿਆਂ ਦੀ ਮੁਹੱਬਤ ਦੇ ਸਨ ਜਿਹੜੇ ਫੋਕੀਆਂ ਰੰਜਸ਼ਾਂ ਤੇ ਰੋਸਿਆਂ ਨੂੰ ਦਿਲਾਂ ਵਿੱਚੋਂ ਹੂੰਝ ਰਹੇ ਸਨ। ਕਰਤਾਰਾ ਭਿੱਜੀਆਂ ਅੱਖਾਂ ਨਾਲ ਸਰਦਾਰੇ ਦੇ ਗਲ ਲੱਗ ਕੇ ਕਹਿਣ ਲੱਗਾ, ''ਭਰਾ, ਮਾਫ਼ ਕਰ ਦੇ। ਅੱਜ ਜੇ ਤੂੰ ਨਾ ਹੁੰਦਾ ਤਾਂ ਸਾਡਾ ਕੀ ਬਣਦਾ!'' ਸਰਦਾਰਾ ਭਰੇ ਮਨ ਨਾਲ ਬੋਲਿਆ, ''ਬਚਾਉਣ ਵਾਲਾ ਤਾਂ ਵਾਹਿਗੁਰੂ ਹੈ ਵੀਰਿਆ। ਜੋ ਹੋਇਆ ਉਹ ਭੁੱਲ ਜਾ। ਅੱਜ ਤੋਂ ਆਪਣਾ ਕੋਈ ਰੋਸਾ ਨਹੀਂ, ਮੈਂ ਹੀ ਗਲਤ ਸਾਂ। ਆਪਣਾ ਸਾਰਾ ਝਗੜਾ ਇਸ ਕਮਰੇ ਦੇ ਨਾਲ ਹੀ ਮੁੱਕ ਗਿਆ ਸਮਝੀਂ।''$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cd0b1bb2-ae1b-4176-b4f3-6245c2048f19', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਬੀਬੀਆਂ ਵੀ ਸਿੱਲ੍ਹੀਆਂ ਅੱਖਾਂ ਨਾਲ ਇੱਕ-ਦੂਜੀ ਨੂੰ ਗਲ ਲਾ ਰਹੀਆਂ ਸਨ। ਹੜ੍ਹਾਂ ਨੇ ਭਾਵੀਂ ਘਰ-ਬਾਰ ਤਬਾਹ ਕਰ ਦਿੱਤੇ ਸਨ ਪਰ ਰਿਸ਼ਤਿਆਂ ਦੇ ਰੇਸ਼ਮੀ ਧਾਗੇ ਹੋਰ ਮਜ਼ਬੂਤ ਹੋ ਗਏ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('184f4862-85f2-482f-8675-7ab3925b7a87', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੜ੍ਹਾਂ ਦੇ ਨਾਲ ਹੀ ਰੋਸੇ, ਗਿਲੇ, ਈਰਖਾ ਤੇ ਦੁਸ਼ਮਣੀਆਂ ਵਹਿ ਗਈਆਂ ਸਨ ਅਤੇ ਇਸ ਦੀ ਥਾਂ ਮੋਹ-ਮੁਹੱਬਤ ਤੇ ਭਾਈਚਾਰੇ ਦੀ ਚਮਕ ਤੇਜ਼ ਹੋ ਗਈ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c78093f2-60c5-4dae-aa85-953031da6db1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$* ਰਿਸ਼ਤਿਆਂ ਦੇ ਮਹੱਤਵ ਤੋਂ ਜਾਣੂ ਹੋਣਾ। * ਮੁਸੀਬਤ ਵਿੱਚ ਇੱਕ-ਦੂਜੇ ਦੀ ਮਦਦ ਕਰਨ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਹੋਣਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('bee66ee0-b9da-489e-9f57-ccf6da807538', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਉ— (ੳ) ਕਿਸੇ ਬਿਪਤਾ ਦੇ ਸਮੇਂ ਲੋਕਾਂ ਨੂੰ ਇੱਕ-ਦੂਜੇ ਦੀ ਮਦਦ ਕਿਉਂ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ? (ਅ) ਕੀ ਤੁਸੀਂ ਆਪਣੇ ਪਿੰਡ/ਸ਼ਹਿਰ ਵਿੱਚ ਕੋਈ ਹੜ੍ਹ ਜਾਂ ਕੁਦਰਤੀ ਆਫ਼ਤ ਦੇਖੀ ਹੈ? (ੲ) ਰਿਸ਼ਤੇ ਬਚਾਉਣ ਲਈ ਸਾਨੂੰ ਕੀ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('feba7c45-5492-4e7f-87d5-9a6d8a1eb495', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '8de2a65e-6f31-4e1c-9361-736130d8b574', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੋਵੇਂ ਪਰਿਵਾਰਾਂ ਦੀਆਂ ਬੀਬੀਆਂ ਵੀ ਸਿੱਲ੍ਹੀਆਂ ਅੱਖਾਂ ਨਾਲ ਇੱਕ-ਦੂਜੀ ਨੂੰ ਗਲ ਲਾ ਰਹੀਆਂ ਸਨ। ਹੜ੍ਹਾਂ ਨੇ ਭਾਵੀਂ ਘਰ-ਬਾਰ ਤਬਾਹ ਕਰ ਦਿੱਤੇ ਸਨ ਪਰ ਰਿਸ਼ਤਿਆਂ ਦੇ ਰੇਸ਼ਮੀ ਧਾਗੇ ਹੋਰ ਮਜ਼ਬੂਤ ਹੋ ਗਏ ਸਨ। ਹੜ੍ਹਾਂ ਦੇ ਨਾਲ ਹੀ ਰੋਸੇ, ਗਿਲੇ, ਈਰਖਾ ਤੇ ਦੁਸ਼ਮਣੀਆਂ ਵਹਿ ਗਈਆਂ ਸਨ ਅਤੇ ਇਸ ਦੀ ਥਾਂ ਮੋਹ-ਮੁਹੱਬਤ ਤੇ ਭਾਈਚਾਰੇ ਦੀ ਚਮਕ ਤੇਜ਼ ਹੋ ਗਈ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-272Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL);
